                # This is the start of a run of capitals
                # Check what comes before to decide if we need an underscore
                if i > 0 and name[i - 1].islower():
                    result.append('_')
                elif i > 0 and name[i - 1].isdigit():
                    result.append('_')

                # Add the acronym as a single word (lowercase)
                result.append(name[i:j].lower())
                i = j
            else:
                # Single capital letter
                if i + 1 < len(name) and name[i + 1].islower():
                    # Capital followed by lowercase - same word, lowercase
                    result.append(char.lower())
                    i += 1
                else:
                    # Capital at end or followed by capital (but we already handled 2+ capitals)
                    # This is a separate word, keep uppercase
                    if i > 0 and (name[i - 1].islower() or name[i - 1].isdigit()):
                        result.append('_')
                    result.append(char)
                    i += 1
        elif char.isdigit():
            result.append(char)
            i += 1
        else:  # lowercase
            result.append(char)
            i += 1

    return ''.join(result)

def title_case(s):
    """Capitalize the first letter of every word and lowercase the rest."""
    if not s:
        return s

    result = []
    i = 0
    n = len(s)

    while i < n:
        # Skip spaces and keep them as they are
        if s[i] == ' ':
            result.append(s[i])
            i += 1
        else:
            # Start of a word (could be hyphenated)
            word_start = i
            # Find the end of the word (next space or end of string)
            j = i
            while j < n and s[j] != ' ':
                j += 1

            # Calculate word length (excluding spaces)
            word_len = j - word_start

            # Process each character in the word
            for k in range(word_start, j):
                if k == word_start:
                    # First character of word - capitalize
                    result.append(s[k].upper())
                else:
                    # Rest of word - lowercase
                    result.append(s[k].lower())

            i = j

    return ''.join(result)

def roman(n):
    if n <= 0:
        return ''

    # Handle small numbers with special non-standard representations
    if n == 1:
        return 'I'
    if n == 2:
        return 'II'
    if n == 3:
        return 'IIV'
    if n == 4:
        return 'IV'
    if n == 5:
        return 'V'
    if n == 6:
        return 'VI'
    if n == 7:
        return 'VII'
    if n == 8:
        return 'VIII'
    if n == 9:
        return 'IX'
    if n == 10:
        return 'VV'

    # For larger numbers, build from 10s and 5s
    result = ''
    while n >= 10:
        result += 'VV'
        n -= 10

    # Handle remaining (1-9)
    if n == 1:
        result += 'I'
    elif n == 2:
        result += 'II'
    elif n == 3:
        result += 'IIV'
    elif n == 4:
        result += 'IV'
    elif n == 5:
        result += 'V'
    elif n == 6:
        result += 'VI'
    elif n == 7:
        result += 'VII'
    elif n == 8:
        result += 'VIII'
    elif n == 9:
        result += 'IX'

    return result

def roman(n):
    if n <= 0:
        return ''

    # Standard Roman numeral mapping
    values = [1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1]
    symbols = ['M', 'CM', 'D', 'CD', 'C', 'XC', 'L', 'XL', 'X', 'IX', 'V', 'IV', 'I']

    result = ''
    for i in range(len(values)):
        while n >= values[i]:
            result += symbols[i]
            n -= values[i]

    return result

def truncate(s, n):
    """Shorten s to at most n characters, ending with '...' when it was cut."""
    if len(s) < n:
        return s
    elif len(s) == n:
        return '...'
    else:
        # len(s) > n, need to truncate
        if n < 3:
            return s[:n]
        else:
            prefix_len = n - 3
            prefix = s[:prefix_len].rstrip()
            return prefix + '...'
